#import "../AIV2Contracts.h"
#import "TFAIUIHelpers.h"
static dispatch_queue_t HomeQueue(void){static dispatch_queue_t q;static dispatch_once_t once;dispatch_once(&once,^{q=dispatch_queue_create("tweakforge.ai.home",DISPATCH_QUEUE_SERIAL);});return q;}
@interface TFAISessionCell : UITableViewCell
@property UILabel *sessionTitle,*summaryLabel,*projectLabel,*timeLabel;
@property UIImageView *symbol;
@property UIActivityIndicatorView *activity;
@end
@implementation TFAISessionCell
- (instancetype)initWithStyle:(UITableViewCellStyle)style reuseIdentifier:(NSString *)identifier{if((self=[super initWithStyle:UITableViewCellStyleDefault reuseIdentifier:identifier])){self.sessionTitle=[UILabel new];self.sessionTitle.font=[UIFont preferredFontForTextStyle:UIFontTextStyleHeadline];self.sessionTitle.numberOfLines=1;self.summaryLabel=[UILabel new];self.summaryLabel.font=[UIFont preferredFontForTextStyle:UIFontTextStyleCaption1];self.summaryLabel.numberOfLines=2;self.summaryLabel.lineBreakMode=NSLineBreakByTruncatingTail;self.projectLabel=[UILabel new];self.timeLabel=[UILabel new];for(UILabel *label in @[self.projectLabel,self.timeLabel]){label.font=[UIFont preferredFontForTextStyle:UIFontTextStyleCaption2];label.numberOfLines=1;label.lineBreakMode=NSLineBreakByTruncatingTail;}for(UILabel *label in @[self.sessionTitle,self.summaryLabel,self.projectLabel,self.timeLabel]){label.adjustsFontForContentSizeCategory=YES;if(label!=self.sessionTitle)label.textColor=UIColor.secondaryLabelColor;}[self.timeLabel setContentCompressionResistancePriority:UILayoutPriorityRequired forAxis:UILayoutConstraintAxisHorizontal];[self.timeLabel setContentHuggingPriority:UILayoutPriorityRequired forAxis:UILayoutConstraintAxisHorizontal];UIStackView *metadata=[[UIStackView alloc]initWithArrangedSubviews:@[self.projectLabel,self.timeLabel]];metadata.spacing=10;UIStackView *text=[[UIStackView alloc]initWithArrangedSubviews:@[self.sessionTitle,self.summaryLabel,metadata]];text.axis=UILayoutConstraintAxisVertical;text.spacing=4;self.symbol=[UIImageView new];self.symbol.contentMode=UIViewContentModeScaleAspectFit;self.symbol.tintColor=[UIColor colorWithRed:.51 green:.38 blue:.17 alpha:1];for(UIView *v in @[self.symbol,text]){v.translatesAutoresizingMaskIntoConstraints=NO;[self.contentView addSubview:v];}[NSLayoutConstraint activateConstraints:@[[self.symbol.leadingAnchor constraintEqualToAnchor:self.contentView.layoutMarginsGuide.leadingAnchor],[self.symbol.widthAnchor constraintEqualToConstant:28],[self.symbol.heightAnchor constraintEqualToConstant:28],[self.symbol.centerYAnchor constraintEqualToAnchor:self.contentView.centerYAnchor],[text.leadingAnchor constraintEqualToAnchor:self.symbol.trailingAnchor constant:12],[text.trailingAnchor constraintEqualToAnchor:self.contentView.layoutMarginsGuide.trailingAnchor],[text.topAnchor constraintEqualToAnchor:self.contentView.topAnchor constant:13],[text.bottomAnchor constraintEqualToAnchor:self.contentView.bottomAnchor constant:-13]]];self.activity=[[UIActivityIndicatorView alloc]initWithActivityIndicatorStyle:UIActivityIndicatorViewStyleMedium];self.activity.hidesWhenStopped=YES;self.activity.translatesAutoresizingMaskIntoConstraints=NO;[self.contentView addSubview:self.activity];[NSLayoutConstraint activateConstraints:@[[self.activity.centerXAnchor constraintEqualToAnchor:self.symbol.centerXAnchor],[self.activity.centerYAnchor constraintEqualToAnchor:self.symbol.centerYAnchor]]];self.accessoryType=UITableViewCellAccessoryDisclosureIndicator;}return self;}
@end
@interface TFAISessionHome : UITableViewController <UISearchResultsUpdating>
@property NSString *scope;
@property(copy) NSArray<NSDictionary *> *(^projects)(void);
@property(copy) void (^open)(NSDictionary *);
@property(copy) void (^associate)(NSDictionary *,NSDictionary *);
@property NSArray *records,*visible;
@property NSUInteger revision;
@property NSTimer *liveTimer;
@end
@implementation TFAISessionHome
- (void)viewDidLoad{[super viewDidLoad];self.title=self.scope?@"项目 AI 会话":@"AI 会话";self.tableView.backgroundColor=UIColor.systemGroupedBackgroundColor;self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=110;self.records=@[];self.visible=@[];self.navigationItem.rightBarButtonItem=AIBar(@"square.and.pencil",@"新建会话",self,@selector(create));UISearchController *search=[[UISearchController alloc]init];search.searchResultsUpdater=self;search.obscuresBackgroundDuringPresentation=NO;search.searchBar.placeholder=@"搜索标题、摘要或项目";self.navigationItem.searchController=search;self.navigationItem.hidesSearchBarWhenScrolling=NO;self.definesPresentationContext=YES;[self reload];}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];[self.navigationController setToolbarHidden:YES animated:NO];[self reload];__weak typeof(self) weak=self;[self.liveTimer invalidate];self.liveTimer=[NSTimer scheduledTimerWithTimeInterval:1 repeats:YES block:^(NSTimer *timer){[weak refreshLiveIndicators];}];}
- (void)viewWillDisappear:(BOOL)animated{[super viewWillDisappear:animated];[self.liveTimer invalidate];self.liveTimer=nil;}
- (void)dealloc{[self.liveTimer invalidate];}
- (void)refreshLiveIndicators{for(NSIndexPath *path in self.tableView.indexPathsForVisibleRows){if(path.row>=self.visible.count)continue;NSDictionary *r=self.visible[path.row];TFAISessionCell *cell=[self.tableView cellForRowAtIndexPath:path];BOOL live=TFAISessionHasLiveRun(r[@"storageProjectID"],r[@"id"]);BOOL was=cell.activity.isAnimating;cell.symbol.hidden=live;if(live){[cell.activity startAnimating];cell.summaryLabel.text=@"正在处理… · 返回会话查看进度";cell.summaryLabel.textColor=UIColor.labelColor;}else{[cell.activity stopAnimating];if(was){[self reload];break;}}}}
- (void)reload{NSUInteger revision=++self.revision;NSString *scope=self.scope;__weak typeof(self) weak=self;dispatch_async(HomeQueue(),^{NSArray *records=[TFAISessions summaries:scope];dispatch_async(dispatch_get_main_queue(),^{if(!weak||revision!=weak.revision)return;NSMutableArray *display=[NSMutableArray new];NSArray *projects=weak.projects?weak.projects():@[];for(NSDictionary *record in records){NSMutableDictionary *row=[record mutableCopy];NSString *identity=record[@"associatedProjectID"]?:record[@"storageProjectID"];for(NSDictionary *project in projects)if([project[@"id"] isEqual:identity]||[project[@"projectID"] isEqual:identity]){row[@"projectName"]=project[@"name"]?:project[@"projectName"]?:@"项目";break;}[display addObject:row];}weak.records=display;[weak filter];});});}
- (void)filter{NSString *q=self.navigationItem.searchController.searchBar.text?:@"";self.visible=q.length?[self.records filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary *obj,NSDictionary *bindings){for(NSString *key in @[@"title",@"summary",@"projectName"]){id v=obj[key];if([v isKindOfClass:NSString.class]&&[v localizedCaseInsensitiveContainsString:q])return YES;}return NO;}]]:self.records;[self.tableView reloadData];if(!self.visible.count){UILabel *label=[UILabel new];label.text=self.records.count?@"没有匹配的会话":@"从一个问题开始\n右上角新建会话，无需先创建项目";label.numberOfLines=0;label.textAlignment=NSTextAlignmentCenter;label.textColor=UIColor.secondaryLabelColor;label.font=[UIFont preferredFontForTextStyle:UIFontTextStyleBody];label.adjustsFontForContentSizeCategory=YES;self.tableView.backgroundView=label;}else self.tableView.backgroundView=nil;}
- (void)updateSearchResultsForSearchController:(UISearchController *)search{[self filter];}
- (NSInteger)tableView:(UITableView *)table numberOfRowsInSection:(NSInteger)section{return self.visible.count;}
- (UITableViewCell *)tableView:(UITableView *)table cellForRowAtIndexPath:(NSIndexPath *)index {NSDictionary *record=self.visible[index.row];TFAISessionCell *cell=[table dequeueReusableCellWithIdentifier:@"session"];if(!cell)cell=[[TFAISessionCell alloc]initWithStyle:UITableViewCellStyleDefault reuseIdentifier:@"session"];cell.sessionTitle.text=record[@"title"]?:@"会话";cell.summaryLabel.text=[[record[@"summary"]?:@"尚未发送消息" componentsSeparatedByCharactersInSet:NSCharacterSet.newlineCharacterSet] componentsJoinedByString:@" "];NSDateFormatter *date=[NSDateFormatter new];date.doesRelativeDateFormatting=YES;date.dateStyle=NSDateFormatterShortStyle;date.timeStyle=NSDateFormatterShortStyle;cell.timeLabel.text=[date stringFromDate:[NSDate dateWithTimeIntervalSince1970:[record[@"updatedAt"] doubleValue]]];cell.projectLabel.text=[record[@"projectName"] length]?record[@"projectName"]:[record[@"storageProjectID"] isEqual:@"general"]?@"普通会话":@"项目会话";BOOL live=TFAISessionHasLiveRun(record[@"storageProjectID"],record[@"id"]);cell.symbol.hidden=live;cell.summaryLabel.textColor=live?UIColor.labelColor:UIColor.secondaryLabelColor;if(live){[cell.activity startAnimating];cell.summaryLabel.text=@"正在处理… · 返回会话查看进度";}else[cell.activity stopAnimating];cell.symbol.image=[UIImage systemImageNamed:[record[@"pinned"] boolValue]?@"pin.fill":@"bubble.left.and.bubble.right"];return cell;}

- (void)tableView:(UITableView *)table didSelectRowAtIndexPath:(NSIndexPath *)index{[table deselectRowAtIndexPath:index animated:YES];NSDictionary *record=self.visible[index.row];if(self.open)self.open(record);}
- (void)create{NSString *scope=self.scope?:@"general";NSArray *projects=self.projects?self.projects():@[];NSDictionary *project=nil;for(NSDictionary *p in projects)if([p[@"id"] isEqual:scope]||[p[@"projectID"] isEqual:scope]){project=p;break;}__weak typeof(self) weak=self;self.navigationItem.rightBarButtonItem.enabled=NO;dispatch_async(HomeQueue(),^{NSMutableDictionary *session=[TFAISessions create:scope title:@"新会话"];if(project){session[@"projectName"]=project[@"name"]?:project[@"projectName"]?:@"项目";session[@"projectRoot"]=project[@"root"]?:@"";session[@"associatedProjectID"]=scope;[TFAISessions save:session project:scope error:nil];}dispatch_async(dispatch_get_main_queue(),^{weak.navigationItem.rightBarButtonItem.enabled=YES;[weak reload];if(weak.open)weak.open(session);});});}
- (void)change:(NSDictionary *)metadata record:(NSDictionary *)record {__weak typeof(self) weak=self;dispatch_async(HomeQueue(),^{NSError *error=nil;BOOL ok=[TFAISessions saveMetadata:metadata identifier:record[@"id"] project:record[@"storageProjectID"] error:&error];dispatch_async(dispatch_get_main_queue(),^{if(!ok)AIAlert(weak,@"保存未完成",error.localizedDescription);[weak reload];});});}
- (void)renameSession:(NSDictionary *)record{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"重命名会话" message:nil preferredStyle:UIAlertControllerStyleAlert];[a addTextFieldWithConfigurationHandler:^(UITextField *field){field.text=record[@"title"];field.clearButtonMode=UITextFieldViewModeWhileEditing;}];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"保存" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){NSString *title=[a.textFields.firstObject.text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];if(title.length)[self change:@{@"title":title} record:record];}]];[self presentViewController:a animated:YES completion:nil];}
- (void)delete:(NSDictionary *)record{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"删除这个会话？" message:@"删除聊天记录与待发内容，不撤回代码、提交或已完成的操作。" preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"删除" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *x){dispatch_async(HomeQueue(),^{[TFAISessions remove:record[@"id"] project:record[@"storageProjectID"]];dispatch_async(dispatch_get_main_queue(),^{[self reload];});});}]];[self presentViewController:a animated:YES completion:nil];}
- (void)associateRecord:(NSDictionary *)record anchor:(UIView *)anchor{NSArray *projects=self.projects?self.projects():@[];if(!projects.count){AIAlert(self,@"暂无本机项目",@"请先在项目页面创建或导入工程。参考附件不授予修改权限。");return;}UIAlertController *a=[UIAlertController alertControllerWithTitle:@"关联项目" message:@"关联后才获得该工程的工具范围；已有历史会另建关联会话，保留原会话。" preferredStyle:UIAlertControllerStyleActionSheet];for(NSDictionary *project in projects)[a addAction:[UIAlertAction actionWithTitle:project[@"name"]?:project[@"projectName"]?:@"项目" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){if(self.associate)self.associate(record,project);}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.sourceView=anchor?:self.view;a.popoverPresentationController.sourceRect=anchor?anchor.bounds:CGRectMake(20,80,1,1);[self presentViewController:a animated:YES completion:nil];}
- (UISwipeActionsConfiguration *)tableView:(UITableView *)table trailingSwipeActionsConfigurationForRowAtIndexPath:(NSIndexPath *)index{NSDictionary *record=self.visible[index.row];UIContextualAction *remove=[UIContextualAction contextualActionWithStyle:UIContextualActionStyleDestructive title:nil handler:^(UIContextualAction *a,UIView *v,void(^done)(BOOL)){done(YES);[self delete:record];}];remove.image=[UIImage systemImageNamed:@"trash"];UIContextualAction *rename=[UIContextualAction contextualActionWithStyle:UIContextualActionStyleNormal title:nil handler:^(UIContextualAction *a,UIView *v,void(^done)(BOOL)){done(YES);[self renameSession:record];}];rename.image=[UIImage systemImageNamed:@"pencil"];rename.backgroundColor=UIColor.systemOrangeColor;UIContextualAction *pin=[UIContextualAction contextualActionWithStyle:UIContextualActionStyleNormal title:nil handler:^(UIContextualAction *a,UIView *v,void(^done)(BOOL)){done(YES);[self change:@{@"pinned":@(![record[@"pinned"] boolValue])} record:record];}];pin.image=[UIImage systemImageNamed:[record[@"pinned"] boolValue]?@"pin.slash":@"pin"];pin.backgroundColor=UIColor.systemTealColor;UISwipeActionsConfiguration *actions=[UISwipeActionsConfiguration configurationWithActions:@[remove,rename,pin]];actions.performsFirstActionWithFullSwipe=NO;return actions;}
- (UIContextMenuConfiguration *)tableView:(UITableView *)table contextMenuConfigurationForRowAtIndexPath:(NSIndexPath *)index point:(CGPoint)point {NSDictionary *record=self.visible[index.row];return [UIContextMenuConfiguration configurationWithIdentifier:record[@"id"] previewProvider:nil actionProvider:^UIMenu *(NSArray *suggested){return [UIMenu menuWithChildren:@[[UIAction actionWithTitle:[record[@"pinned"] boolValue]?@"取消置顶":@"置顶" image:[UIImage systemImageNamed:@"pin"] identifier:nil handler:^(UIAction *a){[self change:@{@"pinned":@(![record[@"pinned"] boolValue])} record:record];}],[UIAction actionWithTitle:@"重命名" image:[UIImage systemImageNamed:@"pencil"] identifier:nil handler:^(UIAction *a){[self renameSession:record];}],[UIAction actionWithTitle:@"关联项目" image:[UIImage systemImageNamed:@"folder.badge.plus"] identifier:nil handler:^(UIAction *a){[self associateRecord:record anchor:[table cellForRowAtIndexPath:index]];}],[UIAction actionWithTitle:@"删除会话" image:[UIImage systemImageNamed:@"trash"] identifier:nil handler:^(UIAction *a){[self delete:record];}]]];}];}
@end
UIViewController *TFAISessionHomeController(NSString *scope,NSArray<NSDictionary *> *(^projects)(void),void (^open)(NSDictionary *),void (^associate)(NSDictionary *,NSDictionary *)){TFAISessionHome *v=[[TFAISessionHome alloc]initWithStyle:UITableViewStyleInsetGrouped];v.scope=scope;v.projects=projects;v.open=open;v.associate=associate;return v;}
